def transform(grid):
    height = len(grid)
    width = len(grid[0])
    color = next((value for row in grid for value in row if value != 0), 0)
    output = [[0] * (width * 3) for _ in range(height * 3)]
    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0:
                for dr in range(height):
                    for dc in range(width):
                        if grid[dr][dc] == 0:
                            output[r * height + dr][c * width + dc] = color
    return output
